const D = { density:.55, energy:.6, speed:1, scale:1, turb:.6, hue:28, x:.5, y:.5, style:'ember', act:'plume', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height;
const clp = (v,a,b)=> v<a?a:(v>b?b:v);
const MAX = 2000;

// ---- half-res feedback smoke buffer, size-keyed cache ----
const FW = Math.max(2, Math.floor(W/2)), FH = Math.max(2, Math.floor(H/2));
if (!S.fb || S.fw !== FW || S.fh !== FH){
  if (S.fb && S.fb.remove) S.fb.remove();
  S.fb = createGraphics(FW, FH);
  S.fb.pixelDensity(1);
  S.fb.colorMode(HSB, 360, 100, 100, 100);
  S.fb.noStroke();
  S.fb.background(0, 0, 5);
  S.fw = FW; S.fh = FH; S.reseed = true;
}

// ---- particles (seed-deterministic), rebuild on seed / size change ----
if (!S.px || S.seedUsed !== P.seed || S.reseed){
  S.reseed = false; S.seedUsed = P.seed;
  S.px = new Float32Array(MAX); S.py = new Float32Array(MAX);
  S.life = new Float32Array(MAX); S.gen = new Uint16Array(MAX);
  const fr = i => { const s = Math.sin(i*127.1 + (P.seed|0)*311.7) * 43758.5453; return s - Math.floor(s); };
  for (let i=0;i<MAX;i++){
    S.px[i] = fr(i*3+1)*FW; S.py[i] = fr(i*3+2)*FH;
    S.life[i] = 24 + fr(i*3+3)*230;
  }
  S.hoff = fr(11)*26;
}

// ---- per-frame field + dramaturgy constants ----
const style = P.style, act = P.act;
const sub = (style === 'ink' || style === 'pencil');
const asDots = (style === 'spark');
const sec = K.section|0, intn = (K.intensity!=null?K.intensity:.6);
const nf = 0.010 / clp(P.scale, 0.3, 3);
const zt = K.t*(0.05 + P.speed*0.09) + (P.seed|0)*0.137;
const eps = 1.5;
const turbAmt = clp(P.turb, 0, 1.5) + A.lowmid*0.6 + K.swell*0.12;
const hh = (a,b)=>{ const s = Math.sin(a*127.1 + b*311.7 + (P.seed|0)*74.7) * 43758.5453; return s - Math.floor(s); };
const psi = (x,y)=>{
  let v = noise(x*nf, y*nf, zt);
  if (turbAmt > 0.001) v += turbAmt*0.42*noise(x*nf*2.4 + 31.7, y*nf*2.4 + 11.3, zt*1.5 + 5.0);
  return v;
};

const gust = (act==='gust') ? (0.5 + (sec%2?0.95:0.25) + K.pulse*0.6) : 1;
let stepPx = (0.7 + P.speed*1.9) * (0.7 + intn*0.55) * gust;
let wx = (P.x-0.5)*2.4*(0.8+P.speed*0.5);
let wy = (P.y-0.5)*2.4*(0.8+P.speed*0.5);
if (act==='plume') wy -= (0.6 + P.speed*0.9);
const cxp = P.x*FW, cyp = P.y*FH;

const baseHue = (((P.hue + S.hoff + sec*6) % 360) + 360) % 360;
const pulse = K.pulse*P.energy*0.5 + A.bass*0.4;

// ---- fade the buffer toward its ground tone ----
let gH, gS, gB;
if (sub){ gH = (style==='ink'?32:34); gS = (style==='ink'?7:4); gB = (style==='ink'?90:86); }
else { gH = (baseHue+300)%360; gS = (style==='aurora'?55:(style==='spark'?45:50)); gB = (style==='spark'?8:13); }
S.fb.push();
S.fb.blendMode(BLEND);
S.fb.noStroke();
const fade = sub ? (7 + P.energy*6) : (style==='spark' ? (12 + P.energy*10) : (6 + P.energy*6));
S.fb.fill(gH, gS, gB, fade);
S.fb.rect(0, 0, FW, FH);

// ---- advect motes through the divergence-free curl field + deposit ----
S.fb.blendMode(sub ? MULTIPLY : ADD);
const activeN = Math.max(24, Math.floor(clp(P.density,0,1)*MAX));
const streakA = (sub ? (16 + P.energy*30) : (8 + P.energy*16)) * gust;
S.fb.strokeWeight(FW > 640 ? (asDots?2.2:1.5) : (asDots?1.8:1.2));
for (let i=0;i<activeN;i++){
  let x = S.px[i], y = S.py[i];
  const d1 = psi(x, y+eps) - psi(x, y-eps);   // vx  ∝ dPsi/dy
  const d2 = psi(x+eps, y) - psi(x-eps, y);   // vy = -dPsi/dx
  let a = Math.atan2(-d2, d1);
  const m = Math.hypot(d1, d2);
  const spd = clp(m/nf*0.9, 0, 1);
  if (act==='vortex'){ const rx=x-cxp, ry=y-cyp; a = a*0.55 + (Math.atan2(ry,rx)+1.5708)*0.45; }
  let nx = x + Math.cos(a)*stepPx + wx;
  let ny = y + Math.sin(a)*stepPx + wy;
  let h,s,b;
  if (sub){
    if (style==='ink'){ h=(baseHue+200)%360; s=68 - spd*26; b=18 + spd*34; }
    else { h=0; s=0; b=22 + spd*30; }
  } else if (style==='aurora'){ h=(130 + spd*62)%360; s=82 - spd*26; b=36 + spd*52 + pulse*28; }
  else if (style==='spark'){ h=(baseHue+180)%360; s=28 - spd*24; b=60 + spd*40 + pulse*36; }
  else { h=(baseHue+262 + spd*105)%360; s=90 - spd*32; b=40 + spd*55 + pulse*30; } // ember
  S.fb.stroke((((h%360)+360)%360), clp(s,0,100), clp(b,0,100), streakA);
  let wrapped=false;
  if (nx<0){nx+=FW;wrapped=true;} else if(nx>=FW){nx-=FW;wrapped=true;}
  if (ny<0){ny+=FH;wrapped=true;} else if(ny>=FH){ny-=FH;wrapped=true;}
  if (wrapped || asDots) S.fb.point(nx, ny); else S.fb.line(x, y, nx, ny);
  S.px[i]=nx; S.py[i]=ny;
  S.life[i]-=1;
  if (S.life[i] <= 0){
    const g = (S.gen[i] = (S.gen[i]+1) & 65535);
    S.px[i] = hh(i, g)*FW; S.py[i] = hh(i+7, g)*FH;
    S.life[i] = 50 + hh(i+3, g)*210;
  }
}
S.fb.blendMode(BLEND);
S.fb.pop();

// ---- composite smoke buffer to full canvas ----
push();
if (P.alpha < 100) tint(0, 0, 100, clp(P.alpha,0,100));
image(S.fb, 0, 0, W, H);
pop();
